<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/backup_step18.php';
$error=null;$notice=null;
try{$pdo=business_db();backup_step18_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=backup_step18_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');if($action==='verify'){$id=(int)($_POST['backup_id']??0);$result=backup_step18_verify_record($pdo,$id,(string)($_POST['passphrase']??''),(int)$user['id']);$notice='Verification: '.strtoupper($result['status']).' • '.$result['detail'];}elseif($action==='cleanup'){if(!security_step17_has_permission($pdo,'backup.manage',$user))throw new RuntimeException('Backup Manage permission is required for retention cleanup.');$n=backup_step18_cleanup_expired($pdo,$orgId,(int)$user['id']);$notice=$n.' expired backup record(s) cleaned.';}}$rows=backup_step18_records($pdo,$orgId,150);}catch(Throwable $e){$error=$e->getMessage();$rows=[];$csrf=$csrf??'';}
function bh_size(int $b):string{if($b<1024)return $b.' B';if($b<1048576)return number_format($b/1024,1).' KB';return number_format($b/1048576,1).' MB';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Backup History - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/step10.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="backup_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 18 • Backup History</small></span></a><div class="os-top-actions"><a class="os-btn" href="backup_create.php">Create</a><a class="os-btn primary" href="backup_center.php">Backup Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Backup</div><nav class="os-nav"><a href="backup_center.php"><i class="dot"></i>Backup Center</a><a href="backup_create.php"><i class="dot"></i>Create Backup</a><a class="active" href="backup_history.php"><i class="dot"></i>History</a><a href="backup_restore.php"><i class="dot"></i>Restore</a><a href="backup_policy.php"><i class="dot"></i>Policy</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">RECOVERY COPIES</div><h1>Track file integrity, cryptographic verification and retention without exposing backup files directly.</h1><p>Download routes require authentication. Verification requires the backup passphrase again because the passphrase is never stored.</p></section><?php if($error):?><div class="pp-alert bad"><strong>History:</strong> <?= backup_step18_h($error) ?></div><?php endif;?><?php if($notice):?><div class="pp-alert good"><?= backup_step18_h($notice) ?></div><?php endif;?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2><?= count($rows) ?> Backup Record(s)</h2><p>Expired files remain as audit records even after retention cleanup removes the package.</p></div><form method="post"><input type="hidden" name="csrf" value="<?= backup_step18_h($csrf??'') ?>"><input type="hidden" name="action" value="cleanup"><button class="os-btn">Clean Expired</button></form></div><?php if(!$rows):?><div class="pp-empty">No backup has been created yet.</div><?php else:?><div style="overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;padding:10px">Backup</th><th style="text-align:left;padding:10px">Type</th><th style="text-align:left;padding:10px">Coverage</th><th style="text-align:left;padding:10px">Integrity</th><th style="text-align:left;padding:10px">Created</th><th style="text-align:left;padding:10px">Actions</th></tr></thead><tbody><?php foreach($rows as $r):$exists=is_file(backup_step18_resolve_path((string)$r['storage_path']));?><tr style="border-top:1px solid #e3ece6"><td style="padding:10px"><b><?= backup_step18_h($r['backup_code']) ?></b><br><small><?= backup_step18_h($r['stored_name']) ?> • <?= backup_step18_h(bh_size((int)$r['file_size'])) ?></small></td><td style="padding:10px"><?= backup_step18_h($r['backup_type']) ?><br><small><?= backup_step18_h($r['status']) ?></small></td><td style="padding:10px"><?= number_format((int)$r['table_count']) ?> tables<br><small><?= number_format((int)$r['row_count']) ?> rows</small></td><td style="padding:10px"><span class="pp-badge <?= $r['verification_status']==='verified'?'':'warn' ?>"><?= backup_step18_h(strtoupper((string)$r['verification_status'])) ?></span><br><small><?= $exists?'file present':'file expired/missing' ?></small></td><td style="padding:10px"><?= backup_step18_h($r['created_at']) ?><br><small><?= backup_step18_h($r['created_by_name']?:'System') ?></small></td><td style="padding:10px"><?php if($exists):?><a class="os-btn" href="backup_download.php?id=<?= (int)$r['id'] ?>">Download</a><form method="post" style="display:flex;gap:6px;margin-top:7px"><input type="hidden" name="csrf" value="<?= backup_step18_h($csrf??'') ?>"><input type="hidden" name="action" value="verify"><input type="hidden" name="backup_id" value="<?= (int)$r['id'] ?>"><input type="password" name="passphrase" required minlength="12" placeholder="Passphrase" style="max-width:180px;padding:8px;border:1px solid #cedbd2;border-radius:9px"><button class="os-btn">Verify</button></form><?php else:?><span class="pp-badge warn">NO FILE</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></div></body></html>